?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($title)?> — SmartToolz</title><meta name="description" content="<?=htmlspecialchars($title)?> online tool"><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script><style>:root{--p:#635bff;--ink:#172033;--muted:#707b8e;--line:#e5e9f0;--bg:#f6f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,Arial,sans-serif}.page{width:min(1050px,calc(100% - 28px));margin:38px auto 70px}.hero,.box{background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 15px 45px rgba(25,35,70,.06)}.hero{padding:34px;margin-bottom:18px}.eyebrow{color:var(--p);font-size:11px;font-weight:900;letter-spacing:1px}.hero h1{font-size:clamp(32px,5vw,48px);letter-spacing:-2px;margin:8px 0}.hero p,.hint{color:var(--muted);line-height:1.65}.box{padding:25px}.box h2{margin:0 0 8px}.input,textarea,select{width:100%;border:1px solid #dfe4ec;border-radius:11px;padding:12px;background:#fff;outline:0;font:inherit;margin:6px 0 12px}textarea{min-height:190px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{border:0;border-radius:11px;padding:12px 17px;background:var(--p);color:#fff;font-weight:800;cursor:pointer}.btn.alt{background:#edf0f5;color:#263148}.buttons{display:flex;gap:8px;flex-wrap:wrap}.out{white-space:pre-wrap;word-break:break-word;background:#f7f8fb;border:1px solid var(--line);border-radius:12px;padding:15px;margin-top:14px;min-height:46px}.preview{display:block;max-width:100%;max-height:520px;margin:15px auto;border-radius:12px}.drop{border:2px dashed #d7dbee;border-radius:16px;padding:34px;text-align:center;color:var(--muted);cursor:pointer}.center{text-align:center}@media(max-width:650px){.row{grid-template-columns:1fr}.hero,.box{padding:22px}}
</style></head><body><main class="page"><section class="hero"><div class="eyebrow">SMARTTOOLZ TOOL</div><h1><?=htmlspecialchars($title)?></h1><p>Fast, simple and browser-based. Your input is processed directly in your browser whenever possible.</p></section><section class="box" id="app"></section></main><?php require_once __DIR__.'/footer.php'; ?><script>
(function(){
'use strict';
var slug=<?=json_encode($slug)?>,app=document.getElementById('app');
function el(s){return app.querySelector(s)}
function btn(text,cls){var b=document.createElement('button');b.className='btn'+(cls?' '+cls:'');b.textContent=text;return b}
function download(blob,name){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},1000)}
function fileBox(accept,multiple){app.innerHTML='<h2>Select file'+(multiple?'s':'')+'</h2><div class="drop" id="drop">Click here or drag & drop</div><input id="files" class="input" type="file" accept="'+accept+'" '+(multiple?'multiple':'')+' hidden><div id="work"></div>';var d=el('#drop'),f=el('#files');d.onclick=function(){f.click()};d.ondragover=function(e){e.preventDefault()};d.ondrop=function(e){e.preventDefault();f.files=e.dataTransfer.files;f.dispatchEvent(new Event('change'))};return f}
function textTool(kind){app.innerHTML='<h2>'+<?=json_encode($title)?>+'</h2><textarea id="src" placeholder="Enter text..."></textarea><div class="buttons"></div><div class="out" id="out"></div>';var run=btn('Process'),copy=btn('Copy','alt');el('.buttons').append(run,copy);run.onclick=function(){var s=el('#src').value,o=s;if(kind==='word')o='Words: '+(s.trim()?s.trim().split(/\s+/).length:0)+'\nCharacters: '+s.length+'\nCharacters without spaces: '+s.replace(/\s/g,'').length+'\nLines: '+(s?s.split(/\r?\n/).length:0);if(kind==='case')o=s.toUpperCase();if(kind==='dup')o=[...new Set(s.split(/\r?\n/))].join('\n');if(kind==='spaces')o=s.replace(/[ \t]+/g,' ').replace(/^ +| +$/gm,'');if(kind==='sort')o=s.split(/\r?\n/).sort(function(a,b){return a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'})}).join('\n');if(kind==='reverse')o=[...s].reverse().join('');if(kind==='slug')o=s.toLowerCase().trim().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-');if(kind==='markdown')o=s.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>');el('#out').textContent=o};copy.onclick=function(){navigator.clipboard&&navigator.clipboard.writeText(el('#out').textContent)}}
function encodeTool(kind){app.innerHTML='<h2>'+<?=json_encode($title)?>+'</h2><textarea id="src"></textarea><button class="btn" id="run">Process</button><textarea id="out" readonly></textarea>';el('#run').onclick=function(){var s=el('#src').value;try{var o='';if(kind==='b64e')o=btoa(unescape(encodeURIComponent(s)));if(kind==='b64d')o=decodeURIComponent(escape(atob(s)));if(kind==='ue')o=encodeURIComponent(s);if(kind==='ud')o=decodeURIComponent(s);if(kind==='he')o=s.replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]});if(kind==='hd'){var t=document.createElement('textarea');t.innerHTML=s;o=t.value}el('#out').value=o}catch(e){el('#out').value='Invalid input: '+e.message}}}
function jsonTool(){app.innerHTML='<h2>JSON Formatter</h2><textarea id="src" placeholder="Paste JSON here..."></textarea><button class="btn" id="run">Format & Validate</button><div class="out" id="out"></div>';el('#run').onclick=function(){try{el('#out').textContent=JSON.stringify(JSON.parse(el('#src').value),null,2)}catch(e){el('#out').textContent='Invalid JSON: '+e.message}}}
function generators(kind){if(kind==='password'){app.innerHTML='<h2>Password Generator</h2><input id="len" class="input" type="number" min="4" max="128" value="16"><button class="btn" id="run">Generate</button><div class="out" id="out"></div>';el('#run').onclick=function(){var chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*';var s='';for(var i=0;i<+el('#len').value;i++)s+=chars[Math.floor(Math.random()*chars.length)];el('#out').textContent=s};return}if(kind==='uuid'){app.innerHTML='<h2>UUID Generator</h2><button class="btn" id="run">Generate UUID</button><div class="out" id="out"></div>';el('#run').onclick=function(){el('#out').textContent=crypto.randomUUID()};return}if(kind==='random'){app.innerHTML='<h2>Random Number Generator</h2><div class="row"><input id="min" class="input" type="number" value="1"><input id="max" class="input" type="number" value="100"></div><button class="btn" id="run">Generate</button><div class="out" id="out"></div>';el('#run').onclick=function(){var a=+el('#min').value,b=+el('#max').value;el('#out').textContent=Math.floor(Math.random()*(b-a+1))+a};return}if(kind==='lorem'){app.innerHTML='<h2>Lorem Ipsum Generator</h2><input id="n" class="input" type="number" min="1" max="20" value="3"><button class="btn" id="run">Generate</button><textarea id="out"></textarea>';el('#run').onclick=function(){var p='Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.';el('#out').value=Array.from({length:+el('#n').value},function(){return p}).join('\n\n')};return}if(kind==='qr'){app.innerHTML='<h2>QR Code Generator</h2><input id="src" class="input" placeholder="Text or URL"><button class="btn" id="run">Create QR</button><div class="center"><canvas id="qr"></canvas></div>';el('#run').onclick=function(){QRCode.toCanvas(el('#qr'),el('#src').value||'SmartToolz',{width:280})}}}
function calc(kind){var html='';if(kind==='age')html='<h2>Age Calculator</h2><input id="dob" class="input" type="date">';if(kind==='percentage')html='<h2>Percentage Calculator</h2><div class="row"><input id="a" class="input" type="number" placeholder="Percentage"><input id="b" class="input" type="number" placeholder="Number"></div>';if(kind==='bmi')html='<h2>BMI Calculator</h2><div class="row"><input id="w" class="input" type="number" placeholder="Weight kg"><input id="h" class="input" type="number" placeholder="Height cm"></div>';if(kind==='unit')html='<h2>Unit Converter</h2><input id="v" class="input" type="number" value="1"><div class="row"><select id="from"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select><select id="to"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select></div>';app.innerHTML=html+'<button class="btn" id="run">Calculate</button><div class="out" id="out"></div>';el('#run').onclick=function(){var o='';if(kind==='age'){if(!el('#dob').value)return;o=(new Date().getFullYear()-new Date(el('#dob').value).getFullYear())+' years (approx.)'}if(kind==='percentage')o=((+el('#a').value*+el('#b').value)/100).toFixed(2);if(kind==='bmi'){var h=+el('#h').value/100;o=(+el('#w').value/(h*h)).toFixed(2)}if(kind==='unit'){var f={m:1,km:1000,ft:.3048,mi:1609.344,kg:1,lb:.453592};o=((+el('#v').value*f[el('#from').value])/f[el('#to').value]).toFixed(6)+' '+el('#to').value}el('#out').textContent=o}}
function imageTool(kind){var f=fileBox('image/*',false);f.onchange=function(){var file=f.files[0],img=new Image();if(!file)return;img.onload=function(){var w=img.width,h=img.height;app.querySelector('#work').innerHTML='<div class="row"><input id="w" class="input" type="number" value="'+w+'"><input id="h" class="input" type="number" value="'+h+'"></div><input id="q" class="input" type="number" min="0.1" max="1" step="0.1" value="0.9"><button class="btn" id="run">Process & Download</button><div class="out" id="out"></div>';el('#run').onclick=function(){var c=document.createElement('canvas');c.width=kind==='compress'?w:+el('#w').value;c.height=kind==='compress'?h:+el('#h').value;c.getContext('2d').drawImage(img,0,0,c.width,c.height);var mime=kind==='png'?'image/png':kind==='webp'?'image/webp':'image/jpeg',ext=kind==='png'?'png':kind==='webp'?'webp':'jpg';c.toBlob(function(b){download(b,'smarttoolz-'+kind+'.'+ext);el('#out').textContent='Done.'},mime,+el('#q').value||.9)}};img.src=URL.createObjectURL(file)}}
function transform(kind){var f=fileBox('image/*',false);f.onchange=function(){var img=new Image();img.onload=function(){app.querySelector('#work').innerHTML='<div class="row"><input id="x" class="input" type="number" value="0"><input id="y" class="input" type="number" value="0"><input id="w" class="input" type="number" value="'+img.width+'"><input id="h" class="input" type="number" value="'+img.height+'"></div><button class="btn" id="run">Apply & Download</button><div class="out" id="out"></div>';el('#run').onclick=function(){var c=document.createElement('canvas'),x=c.getContext('2d'),w=+el('#w').value,h=+el('#h').value;if(kind==='crop'){c.width=w;c.height=h;x.drawImage(img,+el('#x').value,+el('#y').value,w,h,0,0,w,h)}else{c.width=w;c.height=h;x.save();if(kind==='flip')x.scale(-1,1),x.drawImage(img,-w,0,w,h);else x.drawImage(img,0,0,w,h);x.restore()}c.toBlob(function(b){download(b,'smarttoolz-'+kind+'.png');el('#out').textContent='Done.'},'image/png')}};img.src=URL.createObjectURL(f.files[0])}}
function colorTool(){app.innerHTML='<h2>Color Tool</h2><input id="c" type="color" value="#635bff"><input id="hex" class="input" value="#635bff"><button class="btn" id="run">Convert</button><div class="out" id="out"></div>';el('#run').onclick=function(){var h=el('#hex').value;if(!/^#[0-9a-f]{6}$/i.test(h))h=el('#c').value;var n=parseInt(h.slice(1),16),r=n>>16&255,g=n>>8&255,b=n&255;el('#out').textContent='HEX: '+h.toUpperCase()+'\nRGB: '+r+', '+g+', '+b+'\nCSS: rgb('+r+', '+g+', '+b+')'}}
function pdfTool(kind){var f=fileBox('application/pdf',kind==='merge');f.onchange=function(){app.querySelector('#work').innerHTML='<button class="btn" id="run">Process PDF</button><div class="out" id="out"></div>';el('#run').onclick=async function(){try{var fs=[...f.files];if(kind==='merge'){var out=await PDFLib.PDFDocument.create();for(var file of fs){var src=await PDFLib.PDFDocument.load(await file.arrayBuffer());(await out.copyPages(src,src.getPageIndices())).forEach(function(p){out.addPage(p)})}download(new Blob([await out.save()],{type:'application/pdf'}),'merged.pdf');el('#out').textContent='Merged successfully.'}else if(kind==='split'){var src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());for(var i=0;i<src.getPageCount();i++){var one=await PDFLib.PDFDocument.create();one.addPage((await one.copyPages(src,[i]))[0]);download(new Blob([await one.save()],{type:'application/pdf'}),'page-'+(i+1)+'.pdf')}el('#out').textContent='Pages downloaded.'}else{var p=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());download(new Blob([await p.save()],{type:'application/pdf'}),'optimized.pdf');el('#out').textContent='Done.'}}catch(e){el('#out').textContent='Error: '+e.message}}}}
function pdfImages(fmt){var f=fileBox('application/pdf',false);f.onchange=function(){app.querySelector('#work').innerHTML='<button class="btn" id="run">Convert</button><div class="out" id="out"></div>';el('#run').onclick=async function(){pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';var pdf=await pdfjsLib.getDocument({data:await f.files[0].arrayBuffer()}).promise,zip=new JSZip();for(var i=1;i<=pdf.numPages;i++){var page=await pdf.getPage(i),v=page.getViewport({scale:2}),c=document.createElement('canvas');c.width=v.width;c.height=v.height;await page.render({canvasContext:c.getContext('2d'),viewport:v}).promise;var b=await new Promise(function(r){c.toBlob(r,'image/'+fmt)});zip.file('page-'+i+'.'+fmt,await b.arrayBuffer())}download(await zip.generateAsync({type:'blob'}),'pdf-'+fmt+'.zip');el('#out').textContent='Done.'}}
function imagePdf(){var f=fileBox('image/png,image/jpeg',true);f.onchange=function(){app.querySelector('#work').innerHTML='<button class="btn" id="run">Create PDF</button><div class="out" id="out"></div>';el('#run').onclick=async function(){var doc=new jspdf.jsPDF();for(var i=0;i<f.files.length;i++){if(i)doc.addPage();var u=URL.createObjectURL(f.files[i]);await new Promise(function(ok){var im=new Image();im.onload=function(){var w=190,h=w*im.height/im.width;doc.addImage(im,'JPEG',10,10,w,h);URL.revokeObjectURL(u);ok()};im.src=u})}doc.save('images.pdf');el('#out').textContent='PDF created.'}}}
function textPdf(){app.innerHTML='<h2>Text to PDF</h2><textarea id="src"></textarea><button class="btn" id="run">Create PDF</button>';el('#run').onclick=function(){var doc=new jspdf.jsPDF();doc.text(doc.splitTextToSize(el('#src').value,180),15,20);doc.save('text.pdf')}}
function qrReader(){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image();im.onload=function(){var c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);var d=c.getContext('2d').getImageData(0,0,c.width,c.height),q=jsQR(d.data,d.width,d.height);app.querySelector('#work').innerHTML='<div class="out">'+(q?q.data:'No QR code detected.')+'</div>'};im.src=URL.createObjectURL(f.files[0])}}
function meme(){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image();im.onload=function(){app.querySelector('#work').innerHTML='<input id="top" class="input" placeholder="Top text"><input id="bottom" class="input" placeholder="Bottom text"><button class="btn" id="run">Create Meme</button><canvas id="cv" class="preview"></canvas>';el('#run').onclick=function(){var c=el('#cv'),x=c.getContext('2d');c.width=im.width;c.height=im.height;x.drawImage(im,0,0);x.font=Math.max(24,im.width/12)+'px Impact';x.textAlign='center';x.lineWidth=5;x.strokeStyle='#000';x.fillStyle='#fff';[['top',50],['bottom',im.height-30]].forEach(function(a){var t=el('#'+a[0]).value;if(t){x.strokeText(t,c.width/2,a[1]);x.fillText(t,c.width/2,a[1])}});c.toBlob(function(b){download(b,'meme.png')},'image/png')}};im.src=URL.createObjectURL(f.files[0])}}
function main(){var m={'image-compressor':function(){imageTool('compress')},'image-resizer':function(){imageTool('resize')},'jpg-to-png':function(){imageTool('png')},'png-to-jpg':function(){imageTool('jpg')},'webp-to-jpg':function(){imageTool('jpg')},'jpg-to-webp':function(){imageTool('webp')},'png-to-webp':function(){imageTool('webp')},'gif-to-jpg':function(){imageTool('jpg')},'image-cropper':function(){transform('crop')},'image-rotator':function(){transform('rotate')},'image-flipper':function(){transform('flip')},'word-counter':function(){textTool('word')},'case-converter':function(){textTool('case')},'remove-duplicate-lines':function(){textTool('dup')},'remove-extra-spaces':function(){textTool('spaces')},'sort-lines':function(){textTool('sort')},'reverse-text':function(){textTool('reverse')},'text-to-slug':function(){textTool('slug')},'markdown-to-html':function(){textTool('markdown')},'base64-encoder':function(){encodeTool('b64e')},'base64-decoder':function(){encodeTool('b64d')},'url-encoder':function(){encodeTool('ue')},'url-decoder':function(){encodeTool('ud')},'html-encoder':function(){encodeTool('he')},'html-decoder':function(){encodeTool('hd')},'json-formatter':jsonTool,'password-generator':function(){generators('password')},'uuid-generator':function(){generators('uuid')},'random-number-generator':function(){generators('random')},'lorem-ipsum-generator':function(){generators('lorem')},'qr-generator':function(){generators('qr')},'color-picker':colorTool,'color-converter':colorTool,'age-calculator':function(){calc('age')},'percentage-calculator':function(){calc('percentage')},'bmi-calculator':function(){calc('bmi')},'unit-converter':function(){calc('unit')},'pdf-merger':function(){pdfTool('merge')},'pdf-splitter':function(){pdfTool('split')},'pdf-compressor':function(){pdfTool('compress')},'pdf-to-jpg':function(){pdfImages('jpeg')},'pdf-to-png':function(){pdfImages('png')},'png-to-pdf':imagePdf,'text-to-pdf':textPdf,'qr-reader':qrReader,'meme-generator':meme};if(m[slug])m[slug]();else app.innerHTML='<h2>'+<?=json_encode($title)?>+'</h2><p class="hint">This tool is available in the catalogue.</p><a class="btn" href="/smart-toolz/tool.php">Back to All Tools</a>')();
})();
</script></body></html>